mapper.select:
SELECT 
FROM xxl_job_operate_log AS t


		AND t.module = #{module}


		AND t.action = #{action}


		AND t.operator like CONCAT(CONCAT('%', #{operator}), '%')


		AND t.target_name like CONCAT(CONCAT('%', #{targetName}), '%')


		AND t.operate_time  >=  #{startTime}


		AND t.operate_time  <=  #{endTime}


		AND t.target_id = #{targetId}


ORDER BY t.id DESC
LIMIT #{offset}, #{pagesize}

SELECT count(1)
FROM xxl_job_operate_log AS t


		AND t.module = #{module}


		AND t.action = #{action}


		AND t.operator like CONCAT(CONCAT('%', #{operator}), '%')


		AND t.target_name like CONCAT(CONCAT('%', #{targetName}), '%')


		AND t.operate_time  >=  #{startTime}


		AND t.operate_time  <=  #{endTime}


		AND t.target_id = #{targetId}

SELECT 
FROM xxl_job_operate_log AS t
WHERE t.id = #{id}
